-- Plane of Knowledge — gate seasonal event NPCs via content flags + dedupe Rasumus vendors
-- Source: ProjectEQ world dump (db.eqemu.dev); extras flagged per operator (all Frostfell).
-- Idempotent. Scope: poknowledge only.
SET NAMES utf8mb4;
START TRANSACTION;
INSERT INTO content_flags (flag_name, enabled, notes) SELECT 'frostfell', 0, 'Frostfell winter event' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM content_flags WHERE flag_name = 'frostfell');
INSERT INTO content_flags (flag_name, enabled, notes) SELECT 'eq_anniversary', 0, 'EverQuest anniversary event' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM content_flags WHERE flag_name = 'eq_anniversary');
INSERT INTO content_flags (flag_name, enabled, notes) SELECT 'legacy_duplicate', 0, 'Disabled/duplicate spawn gate' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM content_flags WHERE flag_name = 'legacy_duplicate');
